function actionLabel(v:any){const key=String(v||'');const hit=ACTION_LABELS[key];return hit?(lang()==='th'?hit.th:hit.en):key.replaceAll('_',' ')||'—'}
function readableDetails(v:any):string[]{
 if(!v)return ['—']; if(typeof v!=='object')return [String(v)]; const d=v as Record<string,any>; const out:string[]=[];
 if(d.role)out.push(`${lang()==='th'?'บทบาท':'Role'}: ${String(d.role).replaceAll('_',' ')}`);
 if(typeof d.is_active==='boolean')out.push(`${lang()==='th'?'สถานะ':'Status'}: ${d.is_active?(lang()==='th'?'เปิดใช้งาน':'Active'):(lang()==='th'?'ปิดใช้งาน':'Inactive')}`);
 if(d.plan_name||d.plan_code)out.push(`${lang()==='th'?'แพ็กเกจ':'Package'}: ${d.plan_name||d.plan_code}`);
 if(d.reason)out.push(`${lang()==='th'?'เหตุผล':'Reason'}: ${d.reason}`);
 if(d.permissions&&typeof d.permissions==='object'){const enabled=Object.entries(d.permissions).filter(([,x])=>x===true).map(([k])=>ADMIN_PERMISSIONS.find(x=>x[0]===k)?.[lang()==='th'?1:2]||k);if(enabled.length)out.push(`${lang()==='th'?'สิทธิ์':'Permissions'}: ${enabled.join(', ')}`)}
 for(const [k,val] of Object.entries(d)){if(['role','is_active','permissions','plan_name','plan_code','reason'].includes(k)||val==null||typeof val==='object')continue;out.push(`${k.replaceAll('_',' ')}: ${String(val)}`)}
 return out.length?out:['—'];
}
function Pager({page,total,onChange}:{page:number;total:number;onChange:(n:number)=>void}){const pages=Math.max(1,Math.ceil(total/PAGE_SIZE));if(total<=PAGE_SIZE)return null;return <div className={styles.pagination}><button disabled={page<=1} onClick={()=>onChange(page-1)}>‹</button><span>{page} / {pages}</span><button disabled={page>=pages} onClick={()=>onChange(page+1)}>›</button></div>}


