 async function call(name:string,params?:Row){const r=await rpcRequest<Row[]|Row>(name,params); if(r.error) throw new Error(r.error); return Array.isArray(r.data)?r.data:(r.data?[r.data]:[])}
 async function load(){setError('');try{const [u,r,s,p,po,a,v,ad]=await Promise.all([call('admin_center_list_users'),call('admin_center_list_reports'),call('admin_center_list_sales'),call('admin_center_list_plans'),call('admin_center_list_plan_offers_v30').catch(()=>[]),call('admin_center_list_audit').catch(()=>[]),call('get_admin_verification_queue',{p_status:'pending',p_limit:200}).catch(()=>[]),call('admin_center_list_translation_addons_v25').catch(()=>[])]);setUsers(u);setReports(r);setSales(s);setPlans(p);setPlanOffers(po);setAddons(ad);setAudit(a);setPendingCounts({review:v.length,reports:r.filter(x=>!['resolved','dismissed','closed'].includes(String(x.status||'new').toLowerCase())).length})}catch(e){setError(e instanceof Error?e.message:String(e))}}
